      if (existingIndex >= 0) {
        const newCart = [...prev];
        newCart[existingIndex].quantity += tempQuantity;
        newCart[existingIndex].price = finalUnitPrice;
        return newCart;
      }

      return [...prev, { 
        ...selectedItem, 
        price: finalUnitPrice, 
        quantity: tempQuantity, 
        note: tempNote,
        selectedOptions: { ...tempSelectedOptions }
      }];
    });

    closeItemModal();
