ปัญหานี้เกิดจาก **โค้ดภายใน Google Apps Script (หลังบ้านของ Google Sheet)** ครับ ไม่ได้เกี่ยวกับไฟล์โปรแกรมหน้าเว็บ (React Application) ที่ผมดูแลอยู่โดยตรง ทำให้ผมไม่สามารถส่งโค้ดแก้ไขผ่านระบบนี้เข้าไปที่ Sheet ของคุณได้ครับ

ข้อความแจ้งเตือน *"แจ้งเตือน: ข้อมูลลูกค้าถูกล็อค!..."* แสดงว่าใน Apps Script มีการเขียนเงื่อนไขดักไว้ (เช่น เช็คว่าเป็นอีเมล Admin หรือไม่) ซึ่งอาจจะทำงานผิดพลาด

**วิธีแก้ไข (คุณต้องทำใน Google Sheet):**

1.  เปิด Google Sheet นั้นขึ้นมา
2.  ไปที่เมนู **ส่วนขยาย (Extensions)** > **Apps Script**
3.  ในหน้าเขียนโค้ด ให้หาฟังก์ชันที่ชื่อประมาณ `unlockData` หรือ `unlockSheet` (หรือฟังก์ชันที่ผูกกับเมนู "ปลดล็อคแก้ไข")
4.  **ลบโค้ดเดิมในฟังก์ชันนั้นทิ้ง** แล้วแทนที่ด้วยโค้ดนี้ครับ (เป็นการสั่งปลดล็อคทันทีโดยไม่เช็คเงื่อนไข):

```javascript
function unlockData() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var ui = SpreadsheetApp.getUi();

  try {
    // 1. ปลดล็อค Range ทั้งหมดในหน้านี้
    var protections = sheet.getProtections(SpreadsheetApp.ProtectionType.RANGE);
    for (var i = 0; i < protections.length; i++) {
      var protection = protections[i];
      if (protection.canEdit()) {
        protection.remove();
      }
    }

    // 2. ปลดล็อคตัว Sheet เอง (ถ้ามีการล็อคทั้งแผ่น)
    var sheetProtection = sheet.getProtections(SpreadsheetApp.ProtectionType.SHEET)[0];
    if (sheetProtection && sheetProtection.canEdit()) {
      sheetProtection.remove();
    }

    ui.alert("✅ ปลดล็อคเรียบร้อย!\nแก้ไขข้อมูลได้แล้วครับ");

  } catch (e) {
    ui.alert("❌ เกิดข้อผิดพลาด: " + e.message);
  }
}
```

5.  กดปุ่ม **Save (รูปแผ่นดิสก์)**
6.  กลับไปที่หน้า Google Sheet แล้วลองกดเมนู **ปลดล็อคแก้ไข (Unlock)** ใหม่อีกครั้งครับ

*เนื่องจากผมไม่มีสิทธิ์เข้าถึงไฟล์ Apps Script ของคุณโดยตรง จึงต้องรบกวนให้คุณนำโค้ดนี้ไปวางเองครับ*

// --- ตั้งค่ารหัสผ่านสำหรับแก้ไขข้อมูล (Admin) ---
const SHEET_NAME = "Orders";

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = ss.getSheetByName(SHEET_NAME);

    // กำหนดหัวตาราง 10 คอลัมน์ ตามที่คุณต้องการ
    const headers = [
      "วันที่รับออเดอร์", 
      "เวลาที่ลูกค้าสั่งอาหาร", 
      "ลำดับคิว", 
      "ชื่อลูกค้า", 
      "เบอร์โทร", 
      "รายการอาหารที่ลูกค้าสั่ง และจำนวน", 
      "ยอดเงินที่ต้องโอน", 
      "ตำแหน่งแผนที่", 
      "สถานะครัว", 
      "ตรวจเช็คยอดโอน"
    ];

    // ถ้ายังไม่มีชีท หรือหัวตารางไม่ตรง ให้สร้าง/แทรกใหม่
    if (!sheet) {
      sheet = ss.insertSheet(SHEET_NAME);
      sheet.appendRow(headers);
      sheet.setFrozenRows(1); // ตรึงแถวแรก
    } else {
      // ตรวจสอบว่าแถวแรกมีข้อความไหม ถ้าว่างเปล่าให้ใส่หัวตาราง
      const firstCell = sheet.getRange(1, 1).getValue();
      if (firstCell === "") {
        sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
        sheet.setFrozenRows(1);
      }
    }

    // 1. ระบบรันเลขคิวอัตโนมัติ (Reset ทุกวัน)
    const today = new Date();
    const dateStr = Utilities.formatDate(today, "GMT+7", "yyyy-MM-dd");

    const scriptProperties = PropertiesService.getScriptProperties();
    let lastDate = scriptProperties.getProperty("LAST_ORDER_DATE");
    let count = Number(scriptProperties.getProperty("ORDER_COUNT")) || 0;

    if (lastDate !== dateStr) {
      count = 0; // ขึ้นวันใหม่ รีเซ็ตคิวเป็น 0
      scriptProperties.setProperty("LAST_ORDER_DATE", dateStr);
    }

    count++;
    scriptProperties.setProperty("ORDER_COUNT", count.toString());
    const orderNo = "#" + count.toString().padStart(2, '0'); // ผลลัพธ์: #01, #02

    // 2. จัดรูปแบบข้อมูลลงตาราง
    const timeStr = Utilities.formatDate(today, "GMT+7", "HH:mm:ss");

    // รวมรายการอาหาร + Option + Note ไว้ในช่องเดียว
    let itemsStr = data.items.map(i => {
       let txt = `- ${i.name} x${i.quantity}`;
       if (i.selectedOptions) txt += ` (${Object.values(i.selectedOptions).join(',')})`;
       if (i.note) txt += ` [หมายเหตุ: ${i.note}]`; 
       return txt;
    }).join("\n");

    // ถ้ามี Note รวมของออเดอร์ ให้ต่อท้ายไปด้วย
    if (data.note) {
        itemsStr += `\n(หมายเหตุรวม: ${data.note})`;
    }

    // ข้อมูลที่จะลงใน 10 คอลัมน์
    const rowData = [
      dateStr,                    // 1. วันที่รับออเดอร์
      timeStr,                    // 2. เวลาที่ลูกค้าสั่งอาหาร
      orderNo,                    // 3. ลำดับคิว
      data.customerName,          // 4. ชื่อลูกค้า
      "'"+data.customerPhone,     // 5. เบอร์โทร (ใส่ ' นำหน้าเพื่อให้เป็น Text ไม่ตัดศูนย์)
      itemsStr,                   // 6. รายการอาหาร
      data.total,                 // 7. ยอดเงิน
      data.locationLink || "-",   // 8. ตำแหน่งแผนที่
      "รอส่ง (Pending)",          // 9. สถานะครัว (ค่าเริ่มต้น)
      "รอตรวจ (Checking)"         // 10. ตรวจเช็คยอดโอน (ค่าเริ่มต้น)
    ];

    sheet.appendRow(rowData);

    // 3. สร้างปุ่มเลือกสถานะ (Dropdown) ให้แถวล่าสุด
    const lastRow = sheet.getLastRow();

    // Dropdown: สถานะครัว (Column 9)
    const statusRule = SpreadsheetApp.newDataValidation()
      .requireValueInList(["รอส่ง (Pending)", "กำลังทำ (Cooking)", "กำลังส่ง (Delivery)", "ส่งแล้ว (Completed)", "ยกเลิก (Cancelled)"])
      .build();
    sheet.getRange(lastRow, 9).setDataValidation(statusRule);

    // Dropdown: ตรวจเช็คยอดโอน (Column 10)
    const payRule = SpreadsheetApp.newDataValidation()
      .requireValueInList(["รอตรวจ (Checking)", "โอนแล้ว (Verified)", "สลิปปลอม/ไม่มียอด (Invalid)"])
      .build();
    sheet.getRange(lastRow, 10).setDataValidation(payRule);

    return ContentService.createTextOutput(JSON.stringify({ result: "success", orderNo: orderNo })).setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ result: "error", error: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

