/*
  This script provides a lock/unlock mechanism for a Google Sheet.
  It prevents editing of cells outside column I (excluding column I itself)
  unless the sheet is unlocked.
  The unlocking process can be done through a menu option, or via a simple toggle.
*/

// Set the sheet name here
const SHEET_NAME = 'Sheet1';

// Unlock status key
const IS_ADMIN_UNLOCKED = 'isAdminUnlocked';

// Lock/unlock menu name
const MENU_NAME = 'Sheet';

// Password for unlocking
const EDIT_PASSWORD = 'password';

// Function to handle the onOpen event, adding a custom menu
function onOpen(e) {
  SpreadsheetApp.getUi()
    .createMenu(MENU_NAME)
    .addItem('Unlock', 'unlockSheet')
    .addItem('Lock', 'lockSheet')
    .addToUi();
}

// Function to handle the lock action (sets IS_ADMIN_UNLOCKED to false)
function lockSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const userProperties = PropertiesService.getUserProperties();
  userProperties.setProperty(IS_ADMIN_UNLOCKED, 'false');
  Browser.msgBox('Sheet Locked');
}

// Function to handle the unlock action (sets IS_ADMIN_UNLOCKED to true)
function unlockSheet() {
  const userProperties = PropertiesService.getUserProperties();
  userProperties.setProperty(IS_ADMIN_UNLOCKED, 'true');
  Browser.msgBox('Sheet Unlocked');
}

// Function to check if the sheet is currently unlocked
function isUnlocked() {
  const userProperties = PropertiesService.getUserProperties();
  return userProperties.getProperty(IS_ADMIN_UNLOCKED) === 'true';
}

// Function to handle the onEdit event, providing the locking logic
function onEdit(e) {
  // Get the edited range from the event object
  const range = e.range;

  // Check if the edited range is valid and on the specified sheet
  if (!range || range.getSheet().getName() !== SHEET_NAME) {
    return;
  }

  // Get the edited column index
  const col = range.getColumn();

  // If locked and not editing column I or beyond, revert the change
  if (!isUnlocked() && col < 9) {
    range.getSheet().getRange(range.getRow(), range.getColumn()).setValue(e.oldValue);
    Browser.msgBox('Customer data locked!');
  }
}
```

