// --- ตั้งค่า ---
const SHEET_NAME = "Orders";
const EDIT_PASSWORD = "1234"; // รหัสผ่านสำหรับปลดล็อค (ถ้าไม่ได้แก้โค้ดคือ 1234)

// --- ฟังก์ชันรับค่าจาก Web App (React) ---
function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = ss.getSheetByName(SHEET_NAME);

    // กำหนดหัวตาราง
    const headers = [
      "วันที่รับออเดอร์", 
      "เวลาที่ลูกค้าสั่งอาหาร", 
      "ลำดับคิว", 
      "ชื่อลูกค้า", 
      "เบอร์โทร", 
      "รายการอาหารที่ลูกค้าสั่ง และจำนวน", 
      "ยอดเงินที่ต้องโอน", 
      "ตำแหน่งแผนที่", 
      "สถานะครัว", 
      "ตรวจเช็คยอดโอน"
    ];

    if (!sheet) {
      sheet = ss.insertSheet(SHEET_NAME);
      sheet.appendRow(headers);
      sheet.setFrozenRows(1);
    } else {
      const firstCell = sheet.getRange(1, 1).getValue();
      if (firstCell === "") {
        sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
        sheet.setFrozenRows(1);
      }
    }

    // รันเลขคิว
    const today = new Date();
    const dateStr = Utilities.formatDate(today, "GMT+7", "yyyy-MM-dd");

    const scriptProperties = PropertiesService.getScriptProperties();
    let lastDate = scriptProperties.getProperty("LAST_ORDER_DATE");
    let count = Number(scriptProperties.getProperty("ORDER_COUNT")) || 0;

    if (lastDate !== dateStr) {
      count = 0;
      scriptProperties.setProperty("LAST_ORDER_DATE", dateStr);
    }

    count++;
    scriptProperties.setProperty("ORDER_COUNT", count.toString());
    const orderNo = "#" + count.toString().padStart(2, '0');

    // จัดรูปแบบข้อมูล
    const timeStr = Utilities.formatDate(today, "GMT+7", "HH:mm:ss");

    let itemsStr = data.items.map(i => {
       let txt = `- ${i.name} x${i.quantity}`;
       if (i.selectedOptions) txt += ` (${Object.values(i.selectedOptions).join(',')})`;
       if (i.note) txt += ` [หมายเหตุ: ${i.note}]`; 
       return txt;
    }).join("\n");

    if (data.note) {
        itemsStr += `\n(หมายเหตุรวม: ${data.note})`;
    }

    const rowData = [
      dateStr,
      timeStr,
      orderNo,
      data.customerName,
      "'"+data.customerPhone,
      itemsStr,
      data.total,
      data.locationLink || "-",
      "รอส่ง (Pending)",
      "รอตรวจ (Checking)"
    ];

    sheet.appendRow(rowData);

    // สร้าง Dropdown
    const lastRow = sheet.getLastRow();
    const statusRule = SpreadsheetApp.newDataValidation().requireValueInList(["รอส่ง (Pending)", "กำลังทำ (Cooking)", "กำลังส่ง (Delivery)", "ส่งแล้ว (Completed)", "ยกเลิก (Cancelled)"]).build();
    sheet.getRange(lastRow, 9).setDataValidation(statusRule);

    const payRule = SpreadsheetApp.newDataValidation().requireValueInList(["รอตรวจ (Checking)", "โอนแล้ว (Verified)", "สลิปปลอม/ไม่มียอด (Invalid)"]).build();
    sheet.getRange(lastRow, 10).setDataValidation(payRule);

    return ContentService.createTextOutput(JSON.stringify({ result: "success", orderNo: orderNo })).setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ result: "error", error: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- ฟังก์ชันป้องกันการแก้ไข (Security) ---
function onEdit(e) {
  const range = e.range;
  const sheet = range.getSheet();

  if (sheet.getName() !== SHEET_NAME) return;

  // ตรวจสอบสถานะการปลดล็อคจาก Property (หัวใจสำคัญคือบรรทัดนี้)
  var isUnlocked = PropertiesService.getUserProperties().getProperty("IS_ADMIN_UNLOCKED") === "TRUE";

  // คอลัมน์ 1-8 (A-H) คือข้อมูลลูกค้า
  const col = range.getColumn();
  if (col < 9 && !isUnlocked) { 
    e.range.setValue(e.oldValue); // คืนค่าเดิมทันที
    Browser.msgBox("⚠️ แจ้งเตือน: ข้อมูลลูกค้าถูกล็อค! ต้องปลดล็อคเมนู SeoulGood Manager ก่อนแก้ไข");
  }
}

