// --- ฟังก์ชันปลดล็อค (แก้ไขใหม่ให้ถูกต้อง) ---
function unlockSheet() {
  var ui = SpreadsheetApp.getUi();
  // ใส่รหัส 1234 หรือแก้ตัวแปร EDIT_PASSWORD ด้านบน
  var result = ui.prompt('Security Check', 'กรุณาใส่รหัสผ่าน (ค่าเริ่มต้น 1234):', ui.ButtonSet.OK_CANCEL);

  if (result.getSelectedButton() == ui.Button.OK) {
