function showPrintSidebar() {
  var html = HtmlService.createHtmlOutputFromFile('Sidebar')
      .setTitle('ระบบพิมพ์ใบเสร็จ - SeoulGood')
      .setWidth(300);
  SpreadsheetApp.getUi().showSidebar(html);
}

function getSelectedOrderData() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var row = sheet.getActiveCell().getRow();

  if (row < 2) return { error: "กรุณาเลือกแถวที่มีข้อมูลออเดอร์" };

  var date = sheet.getRange(row, 1).getValue();
  var time = sheet.getRange(row, 2).getValue();
  var queue = sheet.getRange(row, 3).getValue();
  var name = sheet.getRange(row, 4).getValue();
  var phone = sheet.getRange(row, 5).getValue();
  var itemsRaw = sheet.getRange(row, 6).getValue();
  var total = sheet.getRange(row, 7).getValue();

  var items = [];
  if (itemsRaw) {
    items = String(itemsRaw).split(',').map(function(i) { return i.trim(); });
  }

  return {
    orderId: queue || '-',
    timestamp: (date ? formatDate(date) : '') + ' ' + (time || ''),
    customerName: name,
    customerPhone: phone,
    items: items, 
    total: total
  };
}

function formatDate(date) {
  if (!date) return '';
  try { return Utilities.formatDate(new Date(date), "GMT+7", "dd/MM/yyyy"); } catch (e) { return date; }
}

