                     {/* Right Icon */}
                     <div className={`animate-bounce bg-white p-1.5 rounded-full shadow-sm ${bannerIndex === 1 ? 'text-[#06C755]' : 'text-orange-600'}`} style={{ animationDelay: '150ms' }}>
