                            <span className={`text-sm font-medium ${isPrinterOnline ? 'text-green-600' : 'text-red-500'}`}>
                                {isPrinterOnline ? 'เชื่อมต่อ Server สำเร็จ' : 'เชื่อมต่อ Server ไม่ได้'}
